import{_ as o,o as s,c as a,ag as r,j as e}from"./chunks/framework.KxDd3USm.js";const _=JSON.parse('{"title":"05.3 死锁 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"05-操作系统/03-死锁.md","filePath":"05-操作系统/03-死锁.md"}'),l={name:"05-操作系统/03-死锁.md"},d={class:"fig"},n={"data-figure-id":"figure-32",viewBox:"0 0 720 232",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"两个形状相同的资源等待环对比：左图中 R1、R2 各只有 1 个实例，P1 申请 R1 而 R1 在 P2 手里，P2 申请 R2 而 R2 在 P1 手里，谁也满足不了，是真死锁；右图中 R2 有 2 个实例且 1 个空闲，P2 的申请能当场满足，于是先跑完并归还，环随即解开"},i={class:"fig"},g={"data-figure-id":"figure-33",viewBox:"0 0 520 212",width:"100%",style:{"max-width":"520px"},role:"img","aria-label":"进程资源图初始状态：圆圈 P1、P2 是进程，方框 R1、R2 是资源并标注总量与空闲量。黑色实线从资源指向进程表示已分配一份，红色虚线从进程指向资源表示还差一份申请"};function x(c,t,h,u,p,q){return s(),a("div",null,[t[4]||(t[4]=r('<h1 id="_05-3-死锁-★★★" tabindex="-1">05.3 死锁 ★★★ <a class="header-anchor" href="#_05-3-死锁-★★★" aria-label="Permalink to &quot;05.3 死锁 ★★★&quot;">​</a></h1><h3 id="死锁是什么、为什么会发生" tabindex="-1">死锁是什么、为什么会发生 <a class="header-anchor" href="#死锁是什么、为什么会发生" aria-label="Permalink to &quot;死锁是什么、为什么会发生&quot;">​</a></h3><p>若干进程互相要对方手里的资源，谁都拿不齐、谁都不放手，全体卡死——这就是死锁。发生死锁必须<strong>同时</strong>满足四个必要条件（背名称+含义，选择题考配对）：</p><table tabindex="0"><thead><tr><th>条件</th><th>含义</th><th>破坏它的预防策略</th></tr></thead><tbody><tr><td><strong>互斥</strong></td><td>资源一次只能一个进程用</td><td>无法破坏（资源物理特性决定）</td></tr><tr><td><strong>请求和保持</strong>（保持和等待）</td><td>占着资源还去申请新的</td><td><strong>一次性申请全部资源（静态分配）</strong></td></tr><tr><td><strong>不剥夺</strong></td><td>别人不能抢走已分配的资源</td><td>允许强行剥夺</td></tr><tr><td><strong>环路等待</strong></td><td>形成&quot;你等我、我等你&quot;的环形链</td><td><strong>资源有序分配法</strong>（全系统资源统一编号、按序申请）</td></tr></tbody></table><p>处理策略四层次：<strong>死锁预防</strong>（破坏四条件之一）→ <strong>死锁避免</strong>（银行家算法，动态判断分配后是否安全）→ <strong>死锁检测与解除</strong>（资源图化简）。破坏&quot;互斥&quot;做不到，破坏其余三个都能预防。</p><p>&quot;环路等待&quot;光看见环还不够，<strong>还要数实例</strong>：同类资源只有一个实例时，环就是死锁判决；只要环上某个申请能被环外的空闲实例当场满足，环就困不住人。两幅环画在一起对比：</p>',6)),e("figure",d,[(s(),a("svg",n,[...t[0]||(t[0]=[r('<defs><marker id="dk-r" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--red)"></path></marker><marker id="dk-a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><text class="tt" x="20" y="22">每类资源 1 实例：环 = 死锁</text><circle class="pc" cx="80" cy="88" r="18"></circle><text class="pl" x="80" y="93">P1</text><circle class="pc" cx="250" cy="172" r="18"></circle><text class="pl" x="250" y="177">P2</text><rect class="rb" x="212" y="74" width="76" height="28" rx="6"></rect><text class="rlab" x="250" y="92">R1（共1，空0）</text><rect class="rb" x="42" y="158" width="76" height="28" rx="6"></rect><text class="rlab" x="80" y="176">R2（共1，空0）</text><path class="req" d="M98 84 H208" marker-end="url(#dk-r)"></path><text class="el" x="130" y="76">申请</text><path class="asg" d="M250 106 V150" marker-end="url(#dk-a)"></path><text class="al" x="256" y="132">已分配</text><path class="req" d="M232 176 H122" marker-end="url(#dk-r)"></path><text class="el" x="150" y="200">申请</text><path class="asg" d="M76 158 V110" marker-end="url(#dk-a)"></path><text class="al" x="14" y="136">已分配</text><text class="tt" x="392" y="22">R2 有 2 实例、1 个空闲：有环也解得开</text><circle class="pc" cx="452" cy="88" r="18"></circle><text class="pl" x="452" y="93">P1</text><circle class="pc" cx="622" cy="172" r="18"></circle><text class="pl" x="622" y="177">P2</text><rect class="rb" x="584" y="74" width="76" height="28" rx="6"></rect><text class="rlab" x="622" y="92">R1（共1，空0）</text><rect class="rb" x="414" y="158" width="76" height="28" rx="6"></rect><text class="rlab" x="452" y="173">R2（共2，空1）</text><path class="req" d="M470 84 H580" marker-end="url(#dk-r)"></path><text class="el" x="502" y="76">申请（等死）</text><path class="asg" d="M622 106 V150" marker-end="url(#dk-a)"></path><path class="req" d="M604 176 H494" marker-end="url(#dk-r)"></path><text class="ok" x="520" y="204">空闲实例当场满足！</text><path class="asg" d="M448 158 V110" marker-end="url(#dk-a)"></path><text class="al" x="652" y="136">P2 跑完归还</text><text class="al" x="20" y="226">红色虚线 = 申请（还没拿到），黑色实线 = 已分配；判环之后逐个问：&quot;这个申请现在能满足吗？&quot;</text>',35)])])),t[1]||(t[1]=e("figcaption",null,'这就是"有环未必死锁"的两种结局：左环每个申请都在等对方先放手；右环 P2 的申请靠环外空闲实例立刻满足，P2 完成后 R1 被归还，P1 跟上——环只是"画得出圈"，卡不卡死要逐边验证。',-1))]),t[5]||(t[5]=r('<h3 id="死锁资源数公式-★★★-必考计算" tabindex="-1">死锁资源数公式（★★★ 必考计算） <a class="header-anchor" href="#死锁资源数公式-★★★-必考计算" aria-label="Permalink to &quot;死锁资源数公式（★★★ 必考计算）&quot;">​</a></h3><ul><li><strong>通用形式</strong>：m 个进程、每个进程最多需要 w 个同类资源、系统共有 n 个资源—— <ul><li><strong>不可能发生死锁的最小资源数</strong>：n = <strong>m×(w−1) + 1</strong>（等价条件：n ≥ m(w−1)+1 时必不死锁）；</li><li><strong>可能发生死锁的最大资源数</strong>：n = <strong>m×(w−1)</strong>（n ≤ m(w−1) 时<strong>可能</strong>死锁，不是必然）。</li><li>推导思路：最坏情况是每个进程都拿到 w−1 个还差 1 个、把资源占光——此时共 m(w−1) 个资源全被占着，人人等资源，死锁；只要再多 1 个资源，就有人能凑齐跑完并释放，死锁解开。</li></ul></li><li><strong>代入算例</strong>：3 个进程各需 4 个资源：不可能死锁的最小 n = 3×(4−1)+1 = 10；n = 9 时可能死锁（3 个进程各持 3 个，全占光）。</li><li><strong>手算口诀</strong>：<strong>&quot;每进程先扣 1，乘完再加 1&quot;</strong>。</li></ul><p>反向题型（给 n 求 w）：3 个进程共享 10 个资源，每个进程最多申请 i 个，问&quot;可能发生死锁的最小 i&quot;——令 3×(i−1) ≥ 10，i−1 ≥ 3.34，i ≥ 4.34，取整数 <strong>i = 5</strong>。（i = 4 时 3×3 = 9 &lt; 10，按鸽笼原理必有一个进程能拿到 4 个而完成，不死锁。）</p><h3 id="进程资源图与-化简-★★" tabindex="-1">进程资源图与&quot;化简&quot;（★★） <a class="header-anchor" href="#进程资源图与-化简-★★" aria-label="Permalink to &quot;进程资源图与&quot;化简&quot;（★★）&quot;">​</a></h3><p><strong>动机</strong>：死锁检测要回答&quot;当前这批进程是否已死锁&quot;。进程资源图用圆圈表示进程、方块表示资源：<strong>进程→资源</strong>的有向边 = 申请，<strong>资源→进程</strong>的边 = 已分配。化简 = 模拟&quot;让能跑完的进程跑完并归还资源&quot;，看能否全清空。</p><p><strong>判定四步模板（背下来直接套）</strong>：</p><ol><li><strong>列剩余</strong>：每种资源空闲量 = 总量 − Σ各进程已占该资源；</li><li><strong>判阻塞</strong>：申请量 &gt; 空闲量的进程是<strong>阻塞结点</strong>，先放一边；</li><li><strong>执行归还</strong>：找申请量 ≤ 空闲量的进程（非阻塞），模拟它跑完并把它占用的<strong>全部</strong>资源交还空闲池，标记已化简；</li><li><strong>循环 / 下结论</strong>：重复 2–3 步直到全化简 → <strong>非死锁</strong>；某轮再也找不到可化简进程而仍有未化简者 → <strong>死锁</strong>。</li></ol><p><strong>代入算例</strong>：R1 总量 2、R2 总量 2。P1 占 R1×1、还申请 R1×1；P2 占 R1×1、R2×1、还申请 R2×1。初始状态画出来（空闲量标在资源框里，判&quot;能不能满足&quot;当场可用）：</p>',8)),e("figure",i,[(s(),a("svg",g,[...t[2]||(t[2]=[r('<defs><marker id="sv-r" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--red)"></path></marker><marker id="sv-a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><text class="tt" x="16" y="20">化简前：谁还卡着、谁能动，全看框里的空闲数</text><circle class="pc" cx="90" cy="66" r="18"></circle><text class="pl" x="90" y="71">P1</text><circle class="pc" cx="90" cy="156" r="18"></circle><text class="pl" x="90" y="161">P2</text><rect class="rb" x="300" y="48" width="96" height="34" rx="6"></rect><text class="rl" x="348" y="62">R1</text><text class="rl" x="348" y="76">共 2 · 空 0</text><rect class="rb" x="300" y="138" width="96" height="34" rx="6"></rect><text class="rl" x="348" y="152">R2</text><text class="rl" x="348" y="166">共 2 · 空 1</text><path class="asg" d="M300 54 L106 56" marker-end="url(#sv-a)"></path><text class="ed" x="200" y="48">分配 R1×1</text><path class="req" d="M106 76 L300 78" marker-end="url(#sv-r)"></path><text class="er" x="200" y="92">申请 R1×1：空闲 0，满足不了</text><path class="asg" d="M300 68 L100 146" marker-end="url(#sv-a)"></path><text class="ed" x="236" y="112">分配 R1×1</text><path class="asg" d="M300 148 L106 150" marker-end="url(#sv-a)"></path><text class="ed" x="200" y="144">分配 R2×1</text><path class="req" d="M106 166 L300 166" marker-end="url(#sv-r)"></path><text class="er" x="200" y="184">申请 R2×1：空闲 1，可满足</text><text class="mt" x="16" y="206">P1 申请被 R1 空 0 卡死（红字）；P2 的申请现在就能被空 1 满足——下一帧就让它跑完。</text>',23)])])),t[3]||(t[3]=e("figcaption",null,"红虚线=还欠着的申请，黑实线=已到手的分配；每一步化简后必须回到图上新刷空闲数再判。",-1))]),t[6]||(t[6]=r('<p>再按&quot;化简 = 让能跑的先跑完&quot;逐帧推（每帧的输入状态、动作、结果全部写清，空闲数不许心算）：</p><table tabindex="0"><thead><tr><th>帧</th><th>输入状态（空闲快照）</th><th>判阻塞</th><th>动作</th><th>动作后结果</th></tr></thead><tbody><tr><td>0</td><td>R1 空 0，R2 空 1（见上图）</td><td>P1 需 R1×1 &gt; 空 0，阻塞；P2 需 R2×1 ≤ 空 1，可跑</td><td>P2 执行完毕，归还它占的 R1×1、R2×1</td><td>P2 划掉；空闲变 R1=1、R2=2</td></tr><tr><td>1</td><td>R1 空 1，R2 空 2</td><td>P1 需 R1×1 ≤ 空 1，可跑</td><td>P1 执行完毕，归还 R1×1</td><td>P1 划掉；空闲变 R1=2、R2=2</td></tr><tr><td>2</td><td>全部节点划掉</td><td>——</td><td>——</td><td><strong>全部化简 → 非死锁</strong> ✓</td></tr></tbody></table><p>对照上面的三帧：本例其实不存在&quot;环&quot;，但即便有环（见&quot;环路等待&quot;一节的双环图），只要每帧都能找到一个&quot;申请 ≤ 空闲&quot;的人，照样能化简到底。</p><p><strong>反例演示（易错）</strong>：① 有环<strong>未必</strong>死锁——要把环和&quot;申请是否卡死&quot;合起来看，能化简就不是死锁；② 一次化简会改变空闲量，<strong>每一步都要重刷剩余再判阻塞</strong>，不能拿最初的状态一路判到底。</p><h3 id="银行家算法-★★★" tabindex="-1">银行家算法（★★★） <a class="header-anchor" href="#银行家算法-★★★" aria-label="Permalink to &quot;银行家算法（★★★）&quot;">​</a></h3><p><strong>动机</strong>：预防策略太死板（一次性分配浪费资源），银行家算法更聪明——每次分配前<strong>先假装分出去，看看能不能找到一个让所有进程都跑完的顺序（安全序列）</strong>：找得到就真分，找不到就不分。银行放贷同理：放钱前先算&quot;这笔放出去后，是否还能让所有贷款人最终都还上钱&quot;。</p><p><strong>判定步骤（五步模板，背下来直接套）</strong>：</p><ol><li>算每个进程的<strong>需求 Need = 最大需求 − 已分配</strong>；</li><li>算<strong>剩余可用 Available</strong> = 资源总量 − 各进程已分配之和；</li><li>在未完成进程中找&quot;Need ≤ Available&quot;的进程，让它<strong>执行完并归还全部已分配资源</strong>（Available += 它的 Allocation），标记完成；</li><li>重复第 3 步，直到所有进程完成（→ <strong>安全</strong>，执行顺序即安全序列）或找不到任何可满足的进程（→ <strong>不安全</strong>，拒绝本次分配）；</li><li>若判断&quot;某进程再申请 X 个能否满足&quot;：先<strong>试探性地</strong>把 X 从 Available 划给它、Need 减 X，再走一遍第 2–4 步；不安全则<strong>回滚并拒绝</strong>。</li></ol><p><strong>代入算例</strong>：资源总量 10。P1 最大 5、已分 3（Need 2）；P2 最大 7、已分 2（Need 5）；P3 最大 6、已分 2（Need 4）。Available = 10 − (3+2+2) = 3。</p><ul><li>Need ≤ 3 的只有 P1（Need 2）→ P1 先跑，归还后 Available = 3+3 = 6；</li><li>此时 P2（Need 5 ≤ 6）、P3（Need 4 ≤ 6）都能跑 → 安全序列有 P1→P2→P3 和 P1→P3→P2 两条。</li></ul><p><strong>第 5 步才真正考&quot;批不批&quot;——同一状态下的两个申请分支</strong>（先试分、再复核，中间态逐步列出）：</p><table tabindex="0"><thead><tr><th>帧</th><th>分支一：P3 再申请 1 个</th><th>分支二：P2 再申请 2 个</th></tr></thead><tbody><tr><td>试分</td><td>Available 3−1=2；P3 已分变 3、Need 变 3</td><td>Available 3−2=1；P2 已分变 4、Need 变 3</td></tr><tr><td>第 1 轮找人</td><td>P1 需 2 ≤ 2 ✓ 跑完归还 3 → Available 2+3=5</td><td>P1 需 2、P2 需 3、P3 需 4，全部 &gt; 1，<strong>没人能动</strong></td></tr><tr><td>第 2 轮</td><td>P3 需 3 ≤ 5 ✓ → Available 8；P2 需 5 ≤ 8 ✓ 全完成（P1→P3→P2）</td><td>——</td></tr><tr><td>结论</td><td>找到安全序列 → <strong>批准</strong>（这次试分落地成真）</td><td>一圈没人能动 → 不安全，<strong>回滚试分、拒绝申请</strong></td></tr></tbody></table><p>变式自查：若是&quot;P3 再申请 2 个&quot;呢？试分后 Available 1，三人 Need {2,3,4} 全大于 1 → 同样拒绝——比分支一只多要 1 个，结论就翻转，这就是&quot;宁可错杀&quot;。</p><p><strong>试分口诀：先划走、再看有没有人能跑完；一圈没人动，就回滚说“不”。</strong></p><p><strong>反例演示（易错）</strong>：① 只要<strong>找到一条</strong>安全序列就算安全，不要求唯一（但做题时若四个选项里三条都不通，剩下的那条就是答案）；② &quot;不安全&quot; ≠ &quot;已死锁&quot;，只是&quot;可能死锁&quot;，银行家算法宁可错杀不肯冒险；③ 算 Available 时忘了用&quot;总量减已分配&quot;，直接拿 Need 求和比较——必错。</p><p><strong>应试动作</strong>：① 死锁资源数公式&quot;每进程先扣 1 乘完再加 1&quot;正反两个方向都要会算；② 四条件与破坏策略配对（一次性分配→破坏请求和保持；有序分配→破坏环路等待）；③ 银行家五步模板背熟，安全序列判定题在草稿上列表（Need / Available 两列）逐步推，每步检查&quot;Need ≤ Available&quot;。</p>',16))])}const m=o(l,[["render",x]]);export{_ as __pageData,m as default};
